// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Bound amount to reasonable values
        amount = bound(amount, 1 ether, 100 ether);

        // Deal ether to this contract so we can send it
        vm.deal(address(this), amount);

        uint256 balanceBefore = address(c).balance;

        // Send ether via fallback
        (bool success, ) = address(c).call{value: amount}("");

        if (amount != 10 ether) {
            // For the reference contract, any value != 10 ether should revert
            assertTrue(!success, "Should have reverted for non-10 ether");
        } else {
            // For 10 ether, should succeed and potentially transfer balance
            if (block.number % 15 == 0) {
                // In this case, balance might decrease (transfer to caller)
                // But the balance cannot increase
                assertTrue(address(c).balance <= balanceBefore - (balanceBefore > 0 ? balanceBefore : 0) + 10 ether);
            } else {
                // Balance should increase exactly by 10 ether
                assertTrue(address(c).balance == balanceBefore + 10 ether);
            }
        }
    }
}

